-- SECURE PLUS 2.1: the database is the system of record. Shared and per-computer settings, themes, workspaces with
-- themes, customer profiles, encrypted tenant secrets, database properties (Production/Test) and client installs.
-- Adds address, phone and e-mail columns to cust.Customer and cust.Contact and connection columns to cust.Tenant.
-- Generated by build/scripts/schema/generate_extension_migration.py. Repeatable: every statement is guarded.

IF SCHEMA_ID(N'secureplus') IS NULL EXEC(N'CREATE SCHEMA [secureplus] AUTHORIZATION [dbo]');
GO
IF COL_LENGTH(N'cust.Customer', N'CustomerKey') IS NULL
    ALTER TABLE [cust].[Customer] ADD [CustomerKey] NVARCHAR(64) NULL;
