-- Settings. Scope 'Shared' applies to every computer; 'Computer' to the named computer only (paths, logging).
IF OBJECT_ID(N'[secureplus].[Setting]', N'U') IS NULL
CREATE TABLE [secureplus].[Setting] (
    [Scope] NVARCHAR(20) NOT NULL,
    [ComputerName] NVARCHAR(128) NOT NULL,
    [SettingKey] NVARCHAR(200) NOT NULL,
    [Value] NVARCHAR(MAX) NULL,
    [ModifiedBy] NVARCHAR(256) NOT NULL,
    [ModifiedAtUtc] DATETIME2 NOT NULL,
    CONSTRAINT [PK_Setting] PRIMARY KEY CLUSTERED ([Scope], [ComputerName], [SettingKey])
);
GO
-- Properties of this database: Mode (Production or Test), organization key check value, imports done.
IF OBJECT_ID(N'[secureplus].[DatabaseProperty]', N'U') IS NULL
CREATE TABLE [secureplus].[DatabaseProperty] (
    [PropertyKey] NVARCHAR(100) NOT NULL,
    [Value] NVARCHAR(2000) NULL,
    [ModifiedBy] NVARCHAR(256) NOT NULL,
    [ModifiedAtUtc] DATETIME2 NOT NULL,
    CONSTRAINT [PK_DatabaseProperty] PRIMARY KEY CLUSTERED ([PropertyKey])
);
GO
-- Named themes (light/dark mode, colours, typography) that workspaces use.
IF OBJECT_ID(N'[secureplus].[Theme]', N'U') IS NULL
CREATE TABLE [secureplus].[Theme] (
    [ThemeKey] NVARCHAR(64) NOT NULL,
    [Name] NVARCHAR(200) NOT NULL,
    [Description] NVARCHAR(1000) NULL,
    [PropertiesJson] NVARCHAR(MAX) NOT NULL,
    [IsSystem] BIT NOT NULL,
    [CreatedBy] NVARCHAR(256) NOT NULL,
    [CreatedAtUtc] DATETIME2 NOT NULL,
    [ModifiedBy] NVARCHAR(256) NULL,
    [ModifiedAtUtc] DATETIME2 NULL,
    CONSTRAINT [PK_Theme] PRIMARY KEY CLUSTERED ([ThemeKey])
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_Theme_Name' AND object_id = OBJECT_ID(N'[secureplus].[Theme]'))
    CREATE UNIQUE NONCLUSTERED INDEX [UX_Theme_Name] ON [secureplus].[Theme] ([Name]);
GO
-- The full customer profile (tenants, contacts, settings) as JSON; projected into cust.Customer, cust.Contact, cust.Tenant and cust.Engagement.
IF OBJECT_ID(N'[secureplus].[CustomerProfile]', N'U') IS NULL
CREATE TABLE [secureplus].[CustomerProfile] (
    [CustomerKey] NVARCHAR(64) NOT NULL,
    [Name] NVARCHAR(200) NOT NULL,
    [ProfileJson] NVARCHAR(MAX) NOT NULL,
    [Version] INT NOT NULL,
    [IsSample] BIT NOT NULL,
    [IsArchived] BIT NOT NULL,
    [CreatedBy] NVARCHAR(256) NOT NULL,
    [CreatedAtUtc] DATETIME2 NOT NULL,
    [ModifiedBy] NVARCHAR(256) NOT NULL,
    [ModifiedAtUtc] DATETIME2 NOT NULL,
    CONSTRAINT [PK_CustomerProfile] PRIMARY KEY CLUSTERED ([CustomerKey])
);
GO
-- Tenant client secrets, encrypted with the organization key (AES-256-GCM). The key is never stored in the database.
IF OBJECT_ID(N'[secureplus].[TenantSecret]', N'U') IS NULL
CREATE TABLE [secureplus].[TenantSecret] (
    [SecretReference] NVARCHAR(300) NOT NULL,
    [CipherText] NVARCHAR(MAX) NOT NULL,
    [KeyId] NVARCHAR(64) NOT NULL,
    [CustomerKey] NVARCHAR(64) NULL,
    [TenantKey] NVARCHAR(64) NULL,
    [ExpiresAtUtc] DATETIME2 NULL,
    [CreatedBy] NVARCHAR(256) NOT NULL,
    [CreatedAtUtc] DATETIME2 NOT NULL,
    [ModifiedBy] NVARCHAR(256) NOT NULL,
    [ModifiedAtUtc] DATETIME2 NOT NULL,
    CONSTRAINT [PK_TenantSecret] PRIMARY KEY CLUSTERED ([SecretReference])
);
GO
-- Computers and users running Secure Plus Agent against this database.
IF OBJECT_ID(N'[secureplus].[ClientInstall]', N'U') IS NULL
CREATE TABLE [secureplus].[ClientInstall] (
    [ComputerName] NVARCHAR(128) NOT NULL,
    [UserName] NVARCHAR(256) NOT NULL,
    [AppVersion] NVARCHAR(50) NOT NULL,
    [FirstSeenUtc] DATETIME2 NOT NULL,
    [LastSeenUtc] DATETIME2 NOT NULL,
    [HasOrganizationKey] BIT NOT NULL,
    CONSTRAINT [PK_ClientInstall] PRIMARY KEY CLUSTERED ([ComputerName], [UserName])
);
GO
